function normalize(value) {
  return String(value || '')
    .replace(/\r\n/g, '\n')
    .replace(/\r/g, '\n')
    .replace(/[\u200B-\u200D\uFEFF]/g, '')
    .replace(/\u00A0/g, ' ')
    .trim();
}

function cleanLine(value) {
  return String(value || '').replace(/\s+/g, ' ').trim();
}

function normalizeWarnings(value) {
  if (!Array.isArray(value)) return [];
