}

const aiPrompt = [
  'EDITOR_INSTRUCTIONS:',
  instructions,
  '',
  'SHOW_TYPE:',
  showType,
  '',
  'CURRENT_GUEST_NAME:',
  guestName || '[not provided]',
  '',
  'CURRENT_DOC_TITLE:',
  docTitle || '[not provided]',
