  if (start !== -1 && end !== -1 && end > start) return JSON.parse(raw.slice(start, end + 1));
  throw new Error('AI response was not valid JSON.');
}
const countWords = (value) => String(value || '').split(/\s+/).filter(Boolean).length;
const FIELDS = {
  business_experience: ['business_experience', 'businessExperience'],
  competitive_edge: ['competitive_edge', 'competitiveEdge'],
  personality: ['personality', 'personality_profile'],
  wildcard: ['wildcard', 'the_wildcard', 'wild_card', 'wildCard'],
};

let needsCondense = false;
const counts = {};
let total = 0;
let condensePrompt = '';
try {
  const aiRaw = generated.output || generated.text || generated.response || generated.message || '';
  const parsed = typeof aiRaw === 'object' ? aiRaw : parseJsonFromAi(aiRaw);
  const paragraphs = {};
  for (const [field, keys] of Object.entries(FIELDS)) {
    const key = keys.find((k) => typeof parsed[k] === 'string' && parsed[k].trim());
    paragraphs[field] = key ? parsed[key].trim() : '';
    counts[field] = countWords(paragraphs[field]);
    total += counts[field];
  }
  needsCondense = passes < CONDENSE_MAX_PASSES && (Object.values(counts).some((n) => n > CONDENSE_MAX_WORDS) || total > CONDENSE_MAX_TOTAL);
  if (needsCondense) {
    condensePrompt = [
      `TARGET: ${CONDENSE_TARGET}.`,
      '',
      `BUSINESS_EXPERIENCE (${counts.business_experience} words):`,
      paragraphs.business_experience,
      '',
      `COMPETITIVE_EDGE (${counts.competitive_edge} words):`,
      paragraphs.competitive_edge,
      '',
      `PERSONALITY (${counts.personality} words):`,
      paragraphs.personality,
      '',
      `WILDCARD (${counts.wildcard} words):`,
      paragraphs.wildcard,
    ].join('\n');
  }
} catch (error) {
  needsCondense = false;
}

return [{
  json: {
    ...generated,
    branded_word_counts: counts,
    branded_total_words: total,
    branded_needs_condense: needsCondense,
    branded_condense_passes: passes,
    condense_prompt: condensePrompt,
  },
}];

// Merge V2 Condensed Profile - takes the Condense agent's four rewritten paragraphs and places them
// into the original extraction JSON (names, warnings and every other field untouched), then hands the
// result back to Check V2 Branded Length (which re-measures and may run one more pass) in the same shape the extractor produces. Any problem with the condensed
// output means that paragraph keeps its original text. Never blocks.
const check = $('Check V2 Branded Length').first().json || {};
const condensedItem = $input.first().json || {};

function parseJsonFromAi(value) {
  const raw = String(value || '').trim();
  if (!raw) throw new Error('AI returned an empty response.');
  try { return JSON.parse(raw); } catch {}
  const fenced = raw.match(/```(?:json)?\s*([\s\S]*?)```/i);
  if (fenced) {
    try { return JSON.parse(fenced[1]); } catch {}
  }
  const start = raw.indexOf('{');
  const end = raw.lastIndexOf('}');
  if (start !== -1 && end !== -1 && end > start) return JSON.parse(raw.slice(start, end + 1));
  throw new Error('AI response was not valid JSON.');
}
const countWords = (value) => String(value || '').split(/\s+/).filter(Boolean).length;
const FIELDS = {
  business_experience: ['business_experience', 'businessExperience'],
  competitive_edge: ['competitive_edge', 'competitiveEdge'],
  personality: ['personality', 'personality_profile'],
  wildcard: ['wildcard', 'the_wildcard', 'wild_card', 'wildCard'],
};
const MIN_WORDS = 15;
const MAX_WORDS = 75; // absolute ceiling; a condensed paragraph must also be shorter than the original

const originalRaw = check.output || check.text || check.response || check.message || '';
let merged = null;
let replaced = [];
try {
  const original = typeof originalRaw === 'object' ? originalRaw : parseJsonFromAi(originalRaw);
  const condensedRaw = condensedItem.output || condensedItem.text || condensedItem.response || condensedItem.message || '';
  const condensed = typeof condensedRaw === 'object' ? condensedRaw : parseJsonFromAi(condensedRaw);
  merged = { ...original };
  for (const [field, keys] of Object.entries(FIELDS)) {
    const originalKey = keys.find((k) => typeof original[k] === 'string' && original[k].trim()) || field;
    const candidate = keys.map((k) => condensed[k]).find((v) => typeof v === 'string' && v.trim());
    if (!candidate) continue;
    const text = candidate.replace(/\s+/g, ' ').trim();
    const words = countWords(text);
    const originalWords = countWords(original[originalKey]);
    if (words < MIN_WORDS || words > MAX_WORDS) continue;
    if (words >= originalWords) continue;
    if (/\[[^\]]+\]/.test(text)) continue;
    merged[originalKey] = text;
    replaced.push(field);
  }
} catch (error) {
  merged = null;
}

if (!merged) {
  return [{ json: { output: typeof originalRaw === 'object' ? JSON.stringify(originalRaw) : String(originalRaw), branded_condensed: false, branded_condense_passes: Number(check.branded_condense_passes || 0) + 1 } }];
}
return [{ json: { output: JSON.stringify(merged), branded_condensed: replaced.length > 0, branded_condensed_fields: replaced, branded_condense_passes: Number(check.branded_condense_passes || 0) + 1 } }];

const body = $input.first().json.body || {};
const asyncJobId = String(body.async_job_id || body.asyncJobId || '').trim();
const asyncMode = body.async_mode === true || body.async_mode === 'true' || Boolean(asyncJobId);
if (asyncJobId) {
  const store = $getWorkflowStaticData('global');
  store.v2_async_jobs = store.v2_async_jobs || {};
  const existing = store.v2_async_jobs[asyncJobId] || {};
  store.v2_async_jobs[asyncJobId] = { ...existing, job_id: asyncJobId, status: 'processing', progress: 'Generating V2 letter', updated_at: new Date().toISOString() };
}
const raw = String(body.content || body.transcript || '').trim();
const rawShowType = String(body.show_type || body.showType || 'normal');
const showType = /mansion/i.test(rawShowType)
  ? 'mansion'
  : /island/i.test(rawShowType)
  ? 'island'
  : /reality/i.test(rawShowType)
  ? 'reality'
  : (rawShowType.toLowerCase().includes('nl') || /next\s*level\s*ceo/i.test(rawShowType) ? 'nlceo' : 'normal');
const deadlineText = String(body.deadline_text || body.deadlineText || 'Sunday 11.59pm EST').trim();
const multiClient = body.multi_client === true || body.multi_client === 'true';
const multiClientLetterCount = [1, 2].includes(Number(body.multi_client_letter_count)) ? Number(body.multi_client_letter_count) : 1;
const targetClientName = String(body.target_client_name || body.targetClientName || '').replace(/\s+/g, ' ').trim();
const targetClientPosition = [1, 2].includes(Number(body.target_client_position)) ? Number(body.target_client_position) : 1;
const clientNames = Array.isArray(body.client_names)
  ? body.client_names.map((name) => String(name || '').replace(/\s+/g, ' ').trim()).filter(Boolean).slice(0, 2)
  : [];
const manualClientName = String(
  body.client_name ||
  body.clientName ||
  body.guest_name_override ||
  body.guestNameOverride ||
  (multiClient ? targetClientName : '') ||
  ''
).replace(/\s+/g, ' ').trim();

if (!raw) throw new Error('No transcript found.');
if (raw.length < 120) throw new Error('Transcript is too short for reliable V2 extraction.');

let cleaned = raw
  .replace(/^WEBVTT.*$/gm, '')
  .replace(/^\d+\s*$/gm, '')
  .replace(/^[\d.]*\d+:\d{2}[:\d.]*\s*-->\s*[\d:. ]+$/gm, '')
  .replace(/\[\d{1,2}:\d{2}(?::\d{2})?\]/g, '')
  .replace(/\(\d{1,2}:\d{2}(?::\d{2})?\)/g, '')
  .replace(/^\s*\d{1,2}:\d{2}(?::\d{2})?\s*-?\s*/gm, '')
  .replace(/[ \t]+/g, ' ')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

return [{
  json: {
    cleaned_transcript: cleaned,
    show_type: showType,
    deadline_text: deadlineText,
    manual_client_name: manualClientName,
    multi_client: multiClient,
    multi_client_letter_count: multiClient ? multiClientLetterCount : 1,
    target_client_name: multiClient ? targetClientName : '',
    target_client_position: multiClient ? targetClientPosition : 1,
    client_names: multiClient ? clientNames : [],
    requested_at: body.timestamp || new Date().toISOString(),
    async_job_id: asyncJobId,
    async_mode: asyncMode
  }
}];

